'use strict';
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#main-nav');
if(menu&&nav){menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.focus()}})}
const search=document.querySelector('#catalog-search'),category=document.querySelector('#catalog-category');
if(search&&category){const items=[...document.querySelectorAll('.product-card')];function filter(){const q=search.value.trim().toLowerCase(),cat=category.value;let count=0;items.forEach(el=>{const show=el.dataset.search.includes(q)&&(cat==='all'||el.dataset.category===cat);el.hidden=!show;if(show)count++});document.querySelector('#catalog-count').textContent=`${count} solution${count===1?'':'s'} found`;document.querySelector('#catalog-empty').hidden=count!==0}search.addEventListener('input',filter);category.addEventListener('change',filter);document.querySelector('#reset-filters').addEventListener('click',()=>{search.value='';category.value='all';filter();search.focus()});filter()}
const cov=document.querySelector('#coverage-form');if(cov){cov.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(cov);const q=new URLSearchParams({service:'coverage',location:String(data.get('location')),task:String(data.get('task'))});location.href='/contact.html?'+q.toString()})}
const form=document.querySelector('#enquiry-form');let generatedBrief='';
if(form){const params=new URLSearchParams(location.search);const srv=params.get('service');const allowed=[...form.elements.service.options].map(o=>o.value);if(allowed.includes(srv))form.elements.service.value=srv;else if(srv){form.elements.service.value='software';form.elements.scope.value='Interested in '+srv.replaceAll('-',' ')+'. '}if(params.get('audience')==='partner')form.elements.audience.value='partner';if(params.get('location'))form.elements.location.value=params.get('location');if(params.get('task'))form.elements.scope.value='Coverage enquiry for '+params.get('task')+'. ';form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const v=new FormData(form);const selected=form.elements.service.selectedOptions[0].textContent;generatedBrief='HEYDOCK PROJECT BRIEF\nIntune Limited trading as HeyDock\n\n'+[['Customer type',v.get('audience')==='partner'?'IT company / partner':'Direct business'],['Company',v.get('company')],['Name',v.get('name')],['Email',v.get('email')],['Service',selected],['Location',v.get('location')],['Timing',v.get('timing')],['Budget indication',v.get('budget')]].map(([k,value])=>k+': '+value).join('\n')+'\n\nRequirements\n'+v.get('scope')+'\n\nGenerated locally. This brief has not been sent and does not create a booking or contract.';document.querySelector('#brief-text').textContent=generatedBrief;document.querySelector('#brief-result').hidden=false;form.hidden=true;document.querySelector('#brief-result').focus()});document.querySelector('#edit-brief').addEventListener('click',()=>{document.querySelector('#brief-result').hidden=true;form.hidden=false;form.elements.company.focus()});document.querySelector('#download-brief').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([generatedBrief],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='HeyDock-project-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
